# 手工集成测试：真实解析 EPUB、切块、调用 Qwen 嵌入并写入 Milvus。
#
# 默认不参与 pytest 运行：本模块标记 integration，addopts 已排除该标记。
# 需人工准备凭据与 Milvus 服务后，显式指定标记执行：
#
#   Windows PowerShell
#     $env:DASHSCOPE_API_KEY = "sk-xxx"
#     $env:RAG_IT_MILVUS_URI = "http://127.0.0.1:19530"
#     $env:RAG_IT_EPUB = "D:/books/sanguo.epub"
#     uv run pytest -m integration -v -s
#
#   macOS 或 Linux
#     DASHSCOPE_API_KEY=sk-xxx uv run pytest -m integration -v -s
#
# 环境变量（凭据与连接信息在运行时单独提供，代码与仓库中不落任何密钥）：
#
# | 变量 | 必填 | 默认值 | 说明 |
# | :--- | :--- | :--- | :--- |
# | DASHSCOPE_API_KEY | 是 | 无 | Qwen 的 API Key |
# | RAG_IT_API_KEY | 否 | 无 | 覆盖上一项，便于切换多套凭据 |
# | RAG_IT_MILVUS_URI | 否 | http://127.0.0.1:19530 | Milvus 地址 |
# | RAG_IT_MILVUS_TOKEN | 否 | 无 | Milvus 鉴权令牌 |
# | RAG_IT_MILVUS_DB | 否 | default | Milvus 数据库名 |
# | RAG_IT_COLLECTION | 否 | rag_data_it_qwen_epub | 集合名 |
# | RAG_IT_MODEL | 否 | qwen3.7-text-embedding | 嵌入模型 |
# | RAG_IT_DIM | 否 | 1024 | 向量维度，须与模型输出一致 |
# | RAG_IT_MAX_CHARS | 否 | 1000 | 单块字符上限，注入各解析器 |
# | RAG_IT_SAFE_MAX_CHARS | 否 | 2000 | 单块安全上限，注入各解析器 |
# | RAG_IT_EPUB | 否 | 桌面首个 epub | 待处理的 EPUB 路径 |
# | RAG_IT_SAMPLE_CHARS | 否 | 3000 | 仅取解析结果前若干字符，控制请求量 |
# | RAG_IT_KEEP | 否 | 空 | 置 1 则跑完保留集合，默认删除 |
#
# 安全约定：只有集合名以 rag_data_it 开头、且 RAG_IT_KEEP 未置 1 时才删除集合，
# 避免误删他人数据。
#
# 说明：切块长度取自 parsing 分区，注入各解析器的 max_chars 与 safe_max_chars。

from __future__ import annotations

import importlib.util
import os
from typing import Any, Dict, List, Union
from openai import OpenAI

import pytest

from rag_data import RagData, Settings
from rag_data.facade import build_logger, build_nlp

# 凭据与连接信息一律来自运行时环境变量，代码中不写默认密钥。
MILVUS_URI = os.environ.get('RAG_IT_MILVUS_URI', 'http://127.0.0.1:19530')
MILVUS_TOKEN = os.environ.get('RAG_IT_MILVUS_TOKEN', 'rag')
MILVUS_DB = os.environ.get('RAG_IT_MILVUS_DB', 'rag_data_it_qwen')
COLLECTION = os.environ.get('RAG_IT_COLLECTION', 'rag_data_it_qwen_epub')
MODEL = os.environ.get('RAG_IT_MODEL', 'qwen3.7-text-embedding')
API_KEY = os.environ.get('RAG_IT_API_KEY') or os.environ.get('DASHSCOPE_API_KEY', 'sk-ws-H.xxx')
SAMPLE_CHARS = int(os.environ.get('RAG_IT_SAMPLE_CHARS', '3000'))
KEEP_COLLECTION = os.environ.get('RAG_IT_KEEP', '') == '1'

# 切块长度上限，经 parsing 分区注入各解析器。
MAX_CHARS = int(os.environ.get('RAG_IT_MAX_CHARS', '500'))
SAFE_MAX_CHARS = int(os.environ.get('RAG_IT_SAFE_MAX_CHARS', '2000'))
SPACY_MODEL = os.environ.get('RAG_IT_SPACY_MODEL', 'zh_core_web_sm')

VECTOR_DIM = int(os.environ.get('RAG_IT_DIM', '1024'))
# DashScope 兼容接口单次最多接受 10 条文本。
QWEN_MAX_BATCH = 10
# 只允许删除该前缀的集合。
COLLECTION_PREFIX = 'rag_data_it'
# 连接别名，避免与其它进程的默认连接串号。
ALIAS = 'rag_data_it'


def _local_epub() -> str:
    # 返回待处理的 epub 路径：环境变量优先，其次取桌面首个 epub。
    override = os.environ.get('RAG_IT_EPUB',"C:\\Users\\loong\\Desktop\\三国演义 ([明] 罗贯中 著  [清] 毛宗岗 等批) (z-library.sk, 1lib.sk, z-lib.sk).epub")
    if override:
        return override
    desktop = os.path.join(os.path.expanduser('~'), 'Desktop')
    if not os.path.isdir(desktop):
        return ''
    files = sorted(name for name in os.listdir(desktop) if name.lower().endswith('.epub'))
    return os.path.join(desktop, files[0]) if files else ''

EPUB_PATH = _local_epub()

requires_api_key = pytest.mark.skipif(
    not API_KEY,
    reason='未提供 API Key：请设置环境变量 DASHSCOPE_API_KEY 或 RAG_IT_API_KEY',
)
requires_pymilvus = pytest.mark.skipif(
    importlib.util.find_spec('pymilvus') is None,
    reason='未安装 pymilvus，请先执行 pip install pymilvus',
)
requires_epub = pytest.mark.skipif(
    not EPUB_PATH or not os.path.exists(EPUB_PATH),
    reason='未提供 EPUB：请设置环境变量 RAG_IT_EPUB 或在桌面放置 epub',
)

pytestmark = [pytest.mark.integration, requires_api_key, requires_pymilvus, requires_epub]

# ---------------- 夹具 ----------------


@pytest.fixture(scope='module')
def it_settings() -> Settings:
    # 按集成测试需要构造配置：qwen 嵌入；凭据与模型来自环境变量。
    return Settings.load(
        parsing={
            'spacy_model': SPACY_MODEL,
            'max_chars': MAX_CHARS,
            'safe_max_chars': SAFE_MAX_CHARS,
        },
        embedding={
            'provider': 'qwen',
            'model': MODEL,
            'api_key': API_KEY,
            'dim': VECTOR_DIM,
            'batch_size': QWEN_MAX_BATCH,
        },
        logging={
            'backend':'loguru',
        },
    )


@pytest.fixture(scope='module')
def app(it_settings) -> RagData:
    # 装配真实门面：真实 Qwen 嵌入与真实 spaCy 句柄；句柄不可用时跳过。
    logger = build_logger(it_settings)
    nlp = build_nlp(it_settings, logger)
    if nlp is None:
        pytest.skip('spaCy 句柄不可用，无法切块')
    return RagData(it_settings, logger=logger, nlp=nlp)

@pytest.fixture(scope='module')
def pymilvus():
    # 惰性导入，未安装时由 pytestmark 先行跳过。
    import pymilvus as module

    return module


def _connect(pymilvus) -> None:
    # 带别名连接，避免与其它进程的默认连接串号。
    kwargs: Dict[str, Any] = {'alias': ALIAS, 'uri': MILVUS_URI, 'db_name': MILVUS_DB}
    if MILVUS_TOKEN:
        kwargs['token'] = MILVUS_TOKEN
    pymilvus.connections.connect(**kwargs)


def _drop_collection(pymilvus) -> None:
    # 删除本测试集合；非约定前缀或显式保留时跳过，避免误删他人数据。
    if KEEP_COLLECTION or not COLLECTION.startswith(COLLECTION_PREFIX):
        return
    # if pymilvus.utility.has_collection(COLLECTION, using=ALIAS):
        # pymilvus.utility.drop_collection(COLLECTION, using=ALIAS)


@pytest.fixture(scope='module')
def collection(pymilvus):
    # 连接 Milvus，重建集合与向量索引，退出时按约定删除。
    _connect(pymilvus)
    _drop_collection(pymilvus)
    schema = pymilvus.CollectionSchema(
        fields=[
            pymilvus.FieldSchema(name='id', dtype=pymilvus.DataType.VARCHAR, is_primary=True, max_length=64),
            pymilvus.FieldSchema(name='source', dtype=pymilvus.DataType.VARCHAR, max_length=512),
            pymilvus.FieldSchema(name='text', dtype=pymilvus.DataType.VARCHAR, max_length=65535),
            pymilvus.FieldSchema(name='vector', dtype=pymilvus.DataType.FLOAT_VECTOR, dim=VECTOR_DIM),
        ],
        description='rag-data epub 集成测试集合',
    )
    handle = pymilvus.Collection(COLLECTION, schema=schema, using=ALIAS)
    handle.create_index(
        'vector',
        {'index_type': 'HNSW', 'metric_type': 'COSINE', 'params': {'M': 16, 'efConstruction': 200}},
    )
    handle.load()
    yield handle
    _drop_collection(pymilvus)
    pymilvus.connections.disconnect(ALIAS)

# ---------------- 嵌入 ----------------


def test_provider_is_qwen(app):
    # 确认装配的确实是配置指定的 qwen provider。
    assert app.settings.embedding.provider == 'qwen'
    assert type(app.embedder.provider).__name__ == 'QwenEmbeddingProvider'
    assert app.embedder.provider.model == MODEL
    assert app.embedder.provider.dim == VECTOR_DIM


# ---------------- 解析与切块 ----------------

def test_chunk_returns_non_empty_blocks(app:RagData):
    text = app.parse(EPUB_PATH)
    assert text
    chunks = app.chunk(EPUB_PATH, text[:SAMPLE_CHARS])
    assert chunks
    assert all(chunk.strip() for chunk in chunks)
    assert app.settings.parsing.max_chars == MAX_CHARS
    print('chunks', len(chunks), 'max_chars', MAX_CHARS, 'sizes', [len(chunk) for chunk in chunks])

# ---------------- 向量化 ----------------

@pytest.mark.skip
def test_vectorize_chunks_returns_vectors(app:RagData):
    result = app.embedder.encode(['向量数据库', 'Milvus 相似度检索'])
    assert len(result) == 2
    assert all(len(vector) == VECTOR_DIM for vector in result)



# ---------------- 写入 Milvus ----------------
@pytest.mark.skip
def test_insert_chunks(app:RagData, collection):
    chunks = ['向量数据库', 'Milvus 相似度检索']
    vectors = app.embedder.encode(chunks)
    ids = ['epub-' + str(index) for index in range(len(chunks))]
    rows = [
        {'id': ids[index], 'source': EPUB_PATH, 'text': chunks[index], 'vector': vectors[index]}
        for index in range(len(chunks))
    ]
    collection.insert(rows)
    collection.flush()
    assert collection.num_entities == len(chunks)

@pytest.mark.skip
def test_insert_epub_chunks(app:RagData, collection):
    BATCH_SIZE = 5

    # 1. 解析与切块
    text = app.parse(EPUB_PATH)
    chunks = app.chunk(EPUB_PATH, text)

    # 2. 按 BATCH_SIZE 循环分批处理并插入 Milvus
    for i in range(0, len(chunks), BATCH_SIZE):
        # 提取当前批次的 chunks
        batch_chunks = chunks[i: i + BATCH_SIZE]

        # 针对当前批次进行向量化编码
        batch_vectors = app.embedder.encode(batch_chunks)

        # 构建当前批次数据行
        batch_rows = []
        for idx_in_batch, (chunk_text, vector) in enumerate(zip(batch_chunks, batch_vectors)):
            global_idx = i + idx_in_batch
            batch_rows.append({
                'id': f'epub-{global_idx}',
                'source': EPUB_PATH,
                'text': chunk_text,
                'vector': vector,
            })

        # 批次写入 Milvus
        collection.insert(batch_rows)

    # 3. 所有批次插入完成后统一下盘刷新数据，提高性能
    collection.flush()

